import math

def is_power_of_two(n):
    """Checks if n is a positive power of two."""
    if n <= 0:
        return False
    return (n & (n - 1) == 0)

solutions = []

# Constraints: n=4, x in [5, 50], x not congruent to 1 mod 3
for x in range(5, 51):
    if x % 3 == 1:
        continue  # Skip based on W2's established constraint

    # Calculate R = x^4 + x - 2
    R = x**4 + x - 2

    if R <= 0:
        # Should not happen for x >= 5, but good practice
        continue

    if is_power_of_two(R):
        # R is 2^k. Find k.
        k = R.bit_length() - 1

        # k must be positive (since R >= 2^1=2 for x>=2). For x=5, R = 628, so k is large.
        # R >= 5^4 + 5 - 2 = 628. So k >= 10.

        solutions.append((x, 4, k))

print("Found solutions (x, n=4, k):")
if solutions:
    for sol in solutions:
        print(sol)
else:
    print("No solutions found in the specified range.")
